package cli

import "github.com/twitch-social-bot/internal/domain"

const dinoArtWidth = avatarWidth

// AvatarForPersona returns the 28x12 Unicode Braille ANSI avatar rows for spec,
// preferring custom YAML avatar_rows, then built-in persona art, and Mochi by default.
func AvatarForPersona(spec *domain.PersonaSpec) []string {
	if spec != nil {
		if len(spec.AvatarRows) > 0 {
			return spec.AvatarRows
		}
		if rows, ok := personaAvatars[spec.ID]; ok {
			return rows
		}
	}
	return personaAvatars["cohost_amigos"]
}

